package com.loadoutstudio;
import com.google.gson.*;import java.util.function.*;import javax.swing.*;import org.junit.Test;import net.runelite.http.api.RuneLiteAPI;import static org.junit.Assert.*;
public class BankMenuWorkflowTest {
 private static JsonObject setup(){JsonObject p=SetupCodec.blank("Bank menu test");SetupCodec.setup(p).getAsJsonArray("inv").set(0,SetupCodec.item(560,15000));SetupCodec.setup(p).getAsJsonArray("inv").set(3,SetupCodec.item(563,1000));SetupCodec.rebuildLayout(p);return p;}
 static class Host extends PanelTest.FakeHost {boolean explicit;public void updateBankFilter(JsonObject p,String scope,Consumer<String> status,Consumer<JsonArray> layout,boolean explicit){this.explicit=explicit;super.updateBankFilter(p,scope,status);}}
 @Test public void menuLayoutActionsUpdateOnlyTheDraftAndSaveItsChosenDirection()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject source=setup(),before=source.deepCopy();p.open(new SetupLibrary.Entry(source));p.layoutFromBankMenu(BankLayouts.Mode.PRESET,false);assertTrue(h.explicit);assertEquals(BankLayouts.generate(source,BankLayouts.Mode.PRESET,false),h.selectedBankSetup.get("layout"));assertNull(h.saved);p.layoutFromBankMenu(BankLayouts.Mode.ZIGZAG,true);assertTrue(h.explicit);assertEquals(BankLayouts.generate(source,BankLayouts.Mode.ZIGZAG,true),h.selectedBankSetup.get("layout"));assertEquals(before,source);OwnedGearPanelTest.click(p,"Save");SetupLibrary.Entry saved=SetupLibrary.read(h.saved,RuneLiteAPI.GSON).setups.get(0);assertEquals(BankLayouts.Mode.ZIGZAG,saved.bankLayout);assertTrue(saved.zigzagBottomToTop);p.dispose();});}
 @Test public void clearAndExplicitActivationUseTheCorrectClaimFlagAndInvalidateClosedMenus()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);assertNull(p.bankMenuToken());p.open(new SetupLibrary.Entry(setup()));String token=p.bankMenuToken();assertNotNull(token);p.activateFromBankMenu();assertTrue(h.explicit);p.clearFromBankMenu();assertFalse(h.explicit);assertFalse(SetupCodec.setup(h.selectedBankSetup).get("fb").getAsBoolean());OwnedGearPanelTest.click(p,"setupToggle:filter");assertTrue(h.explicit);p.clearFromBankMenu();OwnedGearPanelTest.click(p,"Save");p.reloadScope();assertNull(p.bankMenuToken());p.open(new SetupLibrary.Entry(setup()));assertNotEquals(token,p.bankMenuToken());p.dispose();assertNull(p.bankMenuToken());});}
 static class Bank implements StudioBankFilter.Gateway {String active="inventory-setups-example";boolean respect=true,open=true;int opens,closes,paused;public boolean bankOpen(){return open;}public int capacity(){return 1000;}public String activeTag(){return active;}public int canonicalize(int id){return id;}public int variation(int id){return id;}public void register(String t,IntPredicate m){}public void open(String t,int[] layout){active=t;opens++;}public void close(){active=null;closes++;}public void unregister(String t){}public void discardLayout(String t){}public boolean respectOtherFilters(){return respect;}public void pauseOwnedView(){paused++;}}
 @Test public void automaticSelectionYieldsToForeignFiltersButExplicitActionCanClaimTheBank(){Bank bank=new Bank();StudioBankFilter filter=new StudioBankFilter(bank,"studio");assertTrue(filter.select(setup()).startsWith("Another Bank filter"));assertEquals(0,bank.opens);assertEquals(0,bank.closes);assertEquals("inventory-setups-example",bank.active);filter.apply(true);assertEquals("studio",bank.active);assertEquals(1,bank.opens);bank.active="another-user-tag";assertTrue(filter.apply().startsWith("Another Bank filter"));filter.clear();assertEquals("another-user-tag",bank.active);assertEquals(0,bank.closes);}
 @Test public void pendingBankOpenAlsoYieldsAndDoesNotRewriteAnExistingTag(){Bank bank=new Bank();bank.open=false;StudioBankFilter filter=new StudioBankFilter(bank,"studio");assertTrue(filter.select(setup()).contains("Open your Bank"));bank.open=true;filter.apply();assertEquals(0,bank.opens);assertTrue(filter.waiting());assertEquals("inventory-setups-example",bank.active);filter.apply(true);assertEquals(1,bank.opens);assertFalse(filter.waiting());}
 @Test public void coexistenceCanBeDisabledAndNormalUnfilteredBanksStillWork(){Bank bank=new Bank();bank.respect=false;StudioBankFilter filter=new StudioBankFilter(bank,"studio");filter.select(setup());assertEquals(1,bank.opens);filter.clear();bank.respect=true;bank.active=null;filter.select(setup());assertEquals(2,bank.opens);assertEquals("studio",bank.active);}
 @Test public void coexistenceAndLayoutMenuDefaultsAreIndependentFromSetupShortcuts(){LoadoutStudioConfig settings=new LoadoutStudioConfig(){public boolean bankMenu(){return false;}};assertTrue(settings.bankLayoutMenu());assertTrue(settings.respectOtherBankFilters());assertTrue(settings.localDiagnostics());assertFalse(settings.bankMenu());}
}
